files./etc/nginx/conf.d/sites.conf:
# 1 台で 3 つのサイトを受け持つ（名前ごとに証明書を送り分ける）
server {
  listen 443 ssl;
  server_name shop.example;
  ssl_certificate /etc/nginx/certs/shop.crt;
  root /var/www/shop;
}
server {
  listen 443 ssl;
  server_name lib.example www.lib.example;
  ssl_certificate /etc/nginx/certs/lib.crt;
  root /var/www/lib;
}
server {
  listen 443 ssl;
  server_name clinic.example;
  ssl_certificate /etc/nginx/certs/clinic.crt;
  root /var/www/clinic;
}
